const CACHE='sentinel-v040';const FILES=['./','./index.html','./boot.js?v=040','./app.js?v=040','./crypto.js','./modules.js','./auth-config.js','./vendor/supabase.js','./style.css?v=040','./favicon.svg','./vendor/argon2.js','./vendor/jsqr.js'];self.addEventListener('install',e=>{self.skipWaiting();e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)));});self.addEventListener('activate',e=>e.waitUntil(Promise.all([caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))),self.clients.claim()])));self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin||new URL(e.request.url).pathname.startsWith('/downloads/'))return;e.respondWith(fetch(e.request).then(response=>response.ok?response:caches.match(e.request).then(c=>c||response)).catch(()=>caches.match(e.request).then(c=>c||Response.error())));});